  "Share of looking time on the television set (Product_TV)",
  sprintf("Each line is one respondent; mean with 95%% CI in accent.\nPaired t(%d) = %.2f, %s, d_z = %.2f, 95%% CI [%.2f, %.2f]",
          as.integer(res_h1$df), res_h1$t, fp(res_h1$p), res_h1$dz, res_h1$dz_lo, res_h1$dz_hi),
  "SIMULATED teaching data (make_simulated_data.py). Not real viewers.\nDwell time (%) is relative to the time the AOI was active (14 s in Balls, 20 s in Paint).",
  scale_y = scale_y_continuous(limits = c(0, NA), expand = expansion(mult = c(0, 0.06))))
save_fig(fig1, "SIMULATED_fig1_product_dwell_paired.png")

