# ---- Summary tables of the tests, for the results paragraph -----------------
row_of <- function(r) tibble(comparison = r$label, n = r$n, m_balls = r$m_b, m_paint = r$m_p,
                             mean_diff = r$diff, sd_diff = r$sd_diff, diff_ci_low = r$ci_lo, diff_ci_high = r$ci_hi,
                             t = r$t, df = r$df, p = r$p, dz = r$dz, dz_ci_low = r$dz_lo, dz_ci_high = r$dz_hi,
                             wilcoxon_V = r$V, wilcoxon_p = r$p_w)
tests <- bind_rows(
  row_of(res_h1) %>% mutate(comparison = "H1 Product_TV Dwell time (%)"),
  row_of(res_h2) %>% mutate(comparison = "H2 Brand_Logo TTFF AOI (ms), both observed"),
  row_of(res_h2b) %>% mutate(comparison = "H2b Brand_Logo TTFF AOI (ms), never fixated = 5000"),
  row_of(res_h3) %>% mutate(comparison = "H3 Liking (1 to 7)")) %>%
  mutate(across(where(is.numeric) & !any_of(c("p", "wilcoxon_p")), ~ round(.x, 6)),
         p = signif(p, 4), wilcoxon_p = signif(wilcoxon_p, 4))
cat("\n---- Summary of the paired tests (difference = Paint minus Balls) ----\n")
print(as.data.frame(tests %>% mutate(across(where(is.numeric), ~ round(.x, 3)))), row.names = FALSE)
write_csv(tests, "SIMULATED_test_results.csv")
cat("written: SIMULATED_test_results.csv\n")

